import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.lxr64Vqo.js";const u=JSON.parse('{"title":"Android TV & Kodi Guide","description":"","frontmatter":{},"headers":[],"relativePath":"clients/android-tv-kodi.md","filePath":"clients/android-tv-kodi.md","lastUpdated":1795114725000}'),d={name:"clients/android-tv-kodi.md"};function r(n,e,l,s,p,c){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="android-tv-kodi-guide" tabindex="-1">Android TV &amp; Kodi Guide <a class="header-anchor" href="#android-tv-kodi-guide" aria-label="Permalink to &quot;Android TV &amp; Kodi Guide&quot;">​</a></h1><p>NoxMedia can serve media to any Android TV, Google TV, NVIDIA Shield, Fire TV, or Kodi setup across your local network.</p><hr><h2 id="upcoming-native-android-tv-app" tabindex="-1">Upcoming: Native Android TV App <a class="header-anchor" href="#upcoming-native-android-tv-app" aria-label="Permalink to &quot;Upcoming: Native Android TV App&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Native Android TV &amp; Google TV App Coming Soon</strong>: We are actively developing a standalone Android TV application with a native 10-foot D-pad interface, ExoPlayer direct hardware acceleration, and integrated home screen recommendation rows. Check the <a href="/NoxMedia/roadmap">Roadmap</a> for development progress.</p></div><hr><h2 id="current-setup-options" tabindex="-1">Current Setup Options <a class="header-anchor" href="#current-setup-options" aria-label="Permalink to &quot;Current Setup Options&quot;">​</a></h2><p>You can stream to your television through the following methods:</p><h3 id="method-1-nuvio-for-android-tv" tabindex="-1">Method 1: Nuvio for Android TV <a class="header-anchor" href="#method-1-nuvio-for-android-tv" aria-label="Permalink to &quot;Method 1: Nuvio for Android TV&quot;">​</a></h3><p>Install Nuvio on your Android TV or Google TV box, add the NoxMedia manifest URL (<code>http://&lt;YOUR_IP&gt;:8096/manifest.json</code>), and browse with remote control navigation.</p><h3 id="method-2-kodi-via-jellyfin-addon" tabindex="-1">Method 2: Kodi via Jellyfin Addon <a class="header-anchor" href="#method-2-kodi-via-jellyfin-addon" aria-label="Permalink to &quot;Method 2: Kodi via Jellyfin Addon&quot;">​</a></h3><ol><li>Open Kodi on your TV device.</li><li>Install the <strong>Jellyfin for Kodi</strong> addon from the official Kodi / Jellyfin repository.</li><li>Enter your server connection:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.1.15:8096</span></span></code></pre></div></li><li>Choose <strong>Add-on (HTTP Stream)</strong> mode for live cloud streaming.</li><li>Enter <code>NoxMedia</code> as the username and leave the password blank.</li><li>Kodi will populate your TV interface with posters, episode groupings, and custom shelves.</li></ol><hr><h2 id="recommended-tv-players" tabindex="-1">Recommended TV Players <a class="header-anchor" href="#recommended-tv-players" aria-label="Permalink to &quot;Recommended TV Players&quot;">​</a></h2><ul><li><strong>Nuvio</strong>: Clean, fast catalog explorer with direct stream launching.</li><li><strong>Nova Video Player</strong>: Open-source, supports Jellyfin/UPnP shares, and offers hardware acceleration on lower-end chipsets.</li><li><strong>Just Player</strong>: Minimalist ExoPlayer-based player with HDR10+ and Dolby Vision passthrough support.</li></ul>',15)])])}const m=o(d,[["render",r]]);export{u as __pageData,m as default};
